public class AuthorBatchLoader : BatchDataLoader<int, Author>
{
    private readonly IAuthorRepository _repository;

    public AuthorBatchLoader(
        IAuthorRepository repository,
        IBatchScheduler batchScheduler)
        : base(batchScheduler)
    {
        _repository = repository;
    }

    protected override async Task<IReadOnlyDictionary<int, Author>> LoadBatchAsync(
        IReadOnlyList<int> keys,
        CancellationToken cancellationToken)
    {
        var authors = await _repository.GetByIdsAsync(keys);
        return authors.ToDictionary(a => a.Id);
    }
}

public class Book
{
    public int Id { get; set; }
    public int AuthorId { get; set; }

    [Resolver]
    public async Task<Author> GetAuthorAsync(
        AuthorBatchLoader loader)
    {
        return await loader.LoadAsync(AuthorId);
    }
}
